@* Displays a single task card with move buttons *@

<div class="task-card">
    <h4>@Task.Title</h4>
    <p class="assignee">@Task.Assignee</p>
    <span class="priority-badge @PriorityClass">@Task.Priority</span>
    <span class="due-date">@Task.DueDate.ToString("MMM dd")</span>
    <div class="card-actions">
        @if (ShowMoveLeft)
        {
            <button class="btn-move" @onclick="() => OnMoveLeft.InvokeAsync(Task)">← Move Left</button>
        }
        @if (ShowMoveRight)
        {
            <button class="btn-move" @onclick="() => OnMoveRight.InvokeAsync(Task)">Move Right →</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }

    private string PriorityClass => Task.Priority switch
    {
        "High" => "priority-high",
        "Medium" => "priority-medium",
        "Low" => "priority-low",
        _ => ""
    };
}

@* Summary stats bar showing task counts *@

<div class="board-stats">
    <span class="stat">Total: <strong>@Total</strong></span>
    <span class="stat">To Do: <strong>@TodoCount</strong></span>
    <span class="stat">In Progress: <strong>@InProgressCount</strong></span>
    <span class="stat">Done: <strong>@DoneCount</strong></span>
    <span class="stat overdue">Overdue: <strong>@OverdueCount</strong></span>
</div>

@code {
    [Parameter] public int Total { get; set; }
    [Parameter] public int TodoCount { get; set; }
    [Parameter] public int InProgressCount { get; set; }
    [Parameter] public int DoneCount { get; set; }
    [Parameter] public int OverdueCount { get; set; }
}

@* A single Kanban column with header, task cards, and inline add form *@

<div class="kanban-column">
    <div class="column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="OnMoveLeft"
                      OnMoveRight="OnMoveRight" />
        }
    </div>

    @if (showForm)
    {
        <div class="add-task-form">
            <input type="text" placeholder="Title" @bind="newTitle" />
            <input type="text" placeholder="Assignee" @bind="newAssignee" />
            <select @bind="newPriority">
                <option value="High">High</option>
                <option value="Medium">Medium</option>
                <option value="Low">Low</option>
            </select>
            <input type="date" @bind="newDueDate" />
            <div class="form-actions">
                <button class="btn-save" @onclick="HandleSave">Save</button>
                <button class="btn-cancel" @onclick="HandleCancel">Cancel</button>
            </div>
        </div>
    }
    else
    {
        <button class="btn-add-task" @onclick="() => showForm = true">+ Add Task</button>
    }
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = "";
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool ShowMoveLeft { get; set; }
    [Parameter] public bool ShowMoveRight { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<TaskItem> OnMoveRight { get; set; }
    [Parameter] public EventCallback<NewTaskRequest> OnTaskCreated { get; set; }

    private bool showForm;
    private string newTitle = "";
    private string newAssignee = "";
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);

    private async Task HandleSave()
    {
        if (string.IsNullOrWhiteSpace(newTitle)) return;

        await OnTaskCreated.InvokeAsync(new NewTaskRequest(newTitle, newAssignee, newPriority, newDueDate));
        ResetForm();
    }

    private void HandleCancel()
    {
        ResetForm();
    }

    private void ResetForm()
    {
        showForm = false;
        newTitle = "";
        newAssignee = "";
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }
}

