 @code {
     private const string StatusToDo = "To Do";
     private const string StatusInProgress = "In Progress";
     private const string StatusDone = "Done";

     private List<TaskItem> allTasks = new();
     private bool isLoading = true;
     private string? errorMessage;
     private string searchText = "";

     private List<TaskItem> TodoTasks => allTasks.Where(t => t.Status == StatusToDo).ToList();
     private List<TaskItem> InProgressTasks => allTasks.Where(t => t.Status == StatusInProgress).ToList();
     private List<TaskItem> DoneTasks => allTasks.Where(t => t.Status == StatusDone).ToList();
     private int OverdueCount => allTasks.Count(t => t.DueDate < DateTime.Today);

     private List<TaskItem> FilteredTodo => ApplySearch(TodoTasks);
     private List<TaskItem> FilteredInProgress => ApplySearch(InProgressTasks);
     private List<TaskItem> FilteredDone => ApplySearch(DoneTasks);

     private List<TaskItem> ApplySearch(List<TaskItem> tasks)
     {
         if (string.IsNullOrWhiteSpace(searchText))
             return tasks;
         return tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase)).ToList();
     }

     protected override async Task OnInitializedAsync()
     {
         await LoadTasks();
     }

     private async Task LoadTasks()
     {
         try
         {
             isLoading = true;
             errorMessage = null;
             allTasks = await TaskService.GetAllTasksAsync();
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to load tasks: {ex.Message}";
         }
         finally
         {
             isLoading = false;
         }
     }

     private async Task MoveTask(TaskItem task, string newStatus)
     {
         try
         {
             await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
             var index = allTasks.FindIndex(t => t.Id == task.Id);
             if (index >= 0)
             {
                 allTasks[index] = task with { Status = newStatus };
             }
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to move task: {ex.Message}";
         }
     }

     private async Task CreateTask(NewTaskRequest request, string status)
     {
         try
         {
             var created = await TaskService.CreateTaskAsync(request.Title, request.Assignee, request.Priority, request.DueDate);
             allTasks.Add(created with { Status = status });
         }
         catch (Exception ex)
         {
             errorMessage = $"Failed to create task: {ex.Message}";
         }
     }
 }

